function totalMoney(n) {
  const weeks = Math.floor(n / 7);
  const extraDays = n % 7;
  const fullWeeksTotal = 28 * weeks + (7 * weeks * (weeks - 1)) / 2;
  const firstExtra = weeks + 1;
  const extraTotal = extraDays * firstExtra + (extraDays * (extraDays - 1)) / 2;
  return fullWeeksTotal + extraTotal;
}

